      "serverFunctions.builtinRoute": "\u0645\u0633\u06CC\u0631 \u062F\u0627\u062E\u0644\u06CC \u2014 \u0627\u0632 \u062D\u0630\u0641 \u0645\u062D\u0627\u0641\u0638\u062A \u0634\u062F\u0647\u061B \u067E\u0633 \u0627\u0632 \u0627\u06CC\u062C\u0627\u062F \u0642\u0627\u0628\u0644 \u062A\u063A\u06CC\u06CC\u0631 \u0646\u06CC\u0633\u062A",
      "serverFunctions.builtinVmHint": "\u0645\u0633\u06CC\u0631\u0647\u0627\u06CC \u062F\u0627\u062E\u0644\u06CC \u0627\u0632 handler\u0647\u0627\u06CC \u0628\u0648\u0645\u06CC Express \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0645\u06CC\u200C\u06A9\u0646\u0646\u062F. \u0632\u0645\u0627\u0646\u200C\u0633\u0646\u062C \u0648 \u06A9\u0634 \u0628\u0631\u0627\u06CC \u062F\u0631\u062E\u0648\u0627\u0633\u062A\u200C\u0647\u0627\u06CC \u0632\u0646\u062F\u0647 \u0627\u0639\u0645\u0627\u0644 \u0645\u06CC\u200C\u0634\u0648\u062F\u061B \u062D\u0627\u0644\u062A VM \u0648 RAM \u0647\u0646\u06AF\u0627\u0645 \u0627\u062C\u0631\u0627\u06CC sandbox \u062F\u0631 \u06A9\u0646\u0633\u0648\u0644 \u0622\u0632\u0645\u0627\u06CC\u0634 \u0627\u0639\u0645\u0627\u0644 \u0645\u06CC\u200C\u0634\u0648\u062F.",
