      "install.cache.redis.line1": "\u064A\u0633\u062A\u062E\u062F\u0645 \u062E\u0627\u062F\u0645 Redis \u062E\u0627\u0631\u062C\u064A\u064B\u0627 \u064A\u0645\u0643\u0646 \u0644\u0643\u0644 \u0639\u0642\u062F\u0629 \u0641\u064A \u0627\u0644\u0646\u0634\u0631 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064A\u0647.",
      "install.cache.redis.line2": "\u0645\u0634\u0627\u0631\u0643\u0629 \u062D\u0627\u0644\u0629 \u0627\u0644\u062C\u0644\u0633\u0629 \u0648\u0630\u0627\u0643\u0631\u0629 \u0627\u0644\u062A\u062E\u0632\u064A\u0646 \u0627\u0644\u0645\u0624\u0642\u062A \u0639\u0646\u062F \u062A\u0634\u063A\u064A\u0644 \u0639\u0642\u062F \u062E\u062F\u0645\u0629 \u0645\u062A\u0639\u062F\u062F\u0629 \u062E\u0644\u0641 \u0648\u0643\u064A\u0644.",
      "install.cache.redis.line3": "\u064A\u0648\u0635\u0649 \u0628\u0647 \u0639\u0646\u062F\u0645\u0627 \u062A\u0643\u0648\u0646 \u0627\u0644\u0628\u0646\u064A\u0629 \u0645\u0628\u0646\u064A\u0629 \u0639\u0644\u0649 \u0627\u0644\u062F\u0648\u0631 \u0623\u0648 \u0639\u0646\u062F\u0645\u0627 \u062A\u062A\u0648\u0642\u0639 \u0623\u0643\u062B\u0631 \u0645\u0646 \u0639\u0642\u062F\u0629 \u062E\u062F\u0645\u0629 \u0648\u0627\u062D\u062F\u0629.",
      "install.cache.redis.line4": "\u064A\u062A\u0637\u0644\u0628 \u0645\u0636\u064A\u0641 Redis \u0648\u0645\u0646\u0641\u0630\u064B\u0627 \u0648\u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u0627\u062E\u062A\u064A\u0627\u0631\u064A\u0629 \u064A\u0645\u0643\u0646 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064A\u0647\u0627.",
      "install.cache.redis.title": "\u0631\u064A\u062F\u064A\u0633",
      "install.cache.redisConnection": "\u0627\u062A\u0635\u0627\u0644 \u0631\u064A\u062F\u064A\u0633",
      "install.capabilities.intro": "\u0627\u0644\u0639\u0642\u062F \u0645\u0633\u062A\u0642\u0644\u0629 \u2014 \u0641\u0647\u064A \u062A\u0634\u062A\u0631\u0643 \u0641\u0642\u0637 \u0641\u064A PostgreSQL \u0648Redis \u0627\u0644\u0627\u062E\u062A\u064A\u0627\u0631\u064A\u0629. \u0627\u0633\u062A\u062E\u062F\u0645 \u0648\u0643\u064A\u0644\u064B\u0627 \u062E\u0627\u0631\u062C\u064A\u064B\u0627 \u0644\u0645\u0648\u0627\u0632\u0646\u0629 \u062A\u062D\u0645\u064A\u0644 \u0639\u0642\u062F \u0627\u0644\u062E\u062F\u0645\u0629 \u0627\u0644\u0645\u062A\u0639\u062F\u062F\u0629. \u062A\u0634\u063A\u064A\u0644 \u0646\u0638\u0627\u0645 \u0623\u0633\u0627\u0633\u064A \u0648\u0627\u062D\u062F \u0648\u0639\u0642\u062F\u0629 \u0639\u0627\u0645\u0644\u0629 \u0648\u0627\u062D\u062F\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0643\u062B\u0631 \u0644\u0643\u0644 \u0639\u0645\u0644\u064A\u0629 \u0646\u0634\u0631.",
      "install.capabilities.nodeName": "\u0627\u0633\u0645 \u0627\u0644\u0639\u0642\u062F\u0629",
      "install.capabilities.nodeNameAria": "\u0627\u0633\u0645 \u0627\u0644\u0639\u0642\u062F\u0629",
      "install.capabilities.onePerDeployment": "\u0648\u0627\u062D\u062F \u0644\u0643\u0644 \u0639\u0645\u0644\u064A\u0629 \u0646\u0634\u0631",
      "install.capabilities.platform.line1": "\u064A\u0633\u062A\u0636\u064A\u0641 Studio \u0648\u0645\u0635\u0645\u0645 \u0627\u0644\u0645\u0643\u0648\u0646\u0627\u062A \u0648\u0627\u0644\u0625\u0639\u062F\u0627\u062F\u0627\u062A \u0648\u0648\u0627\u062C\u0647\u0627\u062A \u0628\u0631\u0645\u062C\u0629 \u062A\u0637\u0628\u064A\u0642\u0627\u062A \u0627\u0644\u0646\u0638\u0627\u0645 \u0627\u0644\u0645\u0636\u0645\u0646\u0629 \u0639\u0644\u0649 \u0647\u0630\u0647 \u0627\u0644\u0639\u0642\u062F\u0629.",
      "install.capabilities.platform.line2": "\u0642\u0645 \u0628\u062A\u0637\u0648\u064A\u0631 \u0627\u0644\u062A\u0637\u0628\u064A\u0642\u0627\u062A \u0641\u064A Studio \u0648\u0631\u0628\u0637 Git \u0628\u062D\u064A\u062B \u064A\u0638\u0644 \u0645\u0635\u062F\u0631 \u0627\u0644\u0645\u0634\u0631\u0648\u0639 \u062A\u062D\u062A \u0627\u0644\u062A\u062D\u0643\u0645 \u0641\u064A \u0627\u0644\u0625\u0635\u062F\u0627\u0631.",
      "install.capabilities.platform.line3": "\u064A\u0642\u0648\u0645 \u0628\u062A\u0634\u063A\u064A\u0644 \u0645\u0643\u062F\u0633 AppEndO \u0627\u0644\u0645\u062F\u0645\u062C \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0644\u0628\u0646\u0627\u0621 \u0627\u0644\u0646\u0638\u0627\u0645 \u0627\u0644\u0623\u0633\u0627\u0633\u064A \u0648\u062A\u0634\u063A\u064A\u0644\u0647.",
      "install.capabilities.platform.line4": "\u0639\u0642\u062F\u0629 \u0646\u0638\u0627\u0645 \u0623\u0633\u0627\u0633\u064A \u0648\u0627\u062D\u062F\u0629 \u0628\u0627\u0644\u0636\u0628\u0637 \u0644\u0643\u0644 \u0639\u0645\u0644\u064A\u0629 \u0646\u0634\u0631.",
      "install.capabilities.platform.title": "\u0645\u0646\u0635\u0629",
      "install.capabilities.service.line1": "\u064A\u062E\u062F\u0645 \u062A\u0637\u0628\u064A\u0642\u0627\u062A \u0627\u0644\u0645\u0633\u062A\u062E\u062F\u0645 \u0627\u0644\u0646\u0647\u0627\u0626\u064A \u0648\u0627\u0644\u0635\u0641\u062D\u0627\u062A \u0648\u0648\u0627\u062C\u0647\u0627\u062A \u0628\u0631\u0645\u062C\u0629 \u0627\u0644\u062A\u0637\u0628\u064A\u0642\u0627\u062A \u0627\u0644\u062A\u064A \u064A\u0633\u062A\u062E\u062F\u0645\u0647\u0627 \u0627\u0644\u0623\u0634\u062E\u0627\u0635 \u0645\u0628\u0627\u0634\u0631\u0629.",
      "install.capabilities.service.line2": "\u0623\u0636\u0641 \u0627\u0644\u0645\u0632\u064A\u062F \u0645\u0646 \u0639\u0642\u062F \u0627\u0644\u062E\u062F\u0645\u0629 \u062E\u0644\u0641 \u0648\u0643\u064A\u0644 \u062E\u0627\u0631\u062C\u064A \u0623\u0648 \u0645\u0648\u0627\u0632\u0646 \u0627\u0644\u062A\u062D\u0645\u064A\u0644 \u0639\u0646\u062F\u0645\u0627 \u062A\u062D\u062A\u0627\u062C \u0625\u0644\u0649 \u0633\u0639\u0629.",
      "install.capabilities.service.line3": "\u062A\u062A\u0634\u0627\u0631\u0643 \u0627\u0644\u0639\u0642\u062F \u0641\u0642\u0637 \u0641\u064A \u0642\u0627\u0639\u062F\u0629 \u0628\u064A\u0627\u0646\u0627\u062A \u0645\u0633\u062A\u0648\u0649 \u0627\u0644\u062A\u062D\u0643\u0645 \u0648Redis \u0627\u0644\u0627\u062E\u062A\u064A\u0627\u0631\u064A\u0629\u060C \u0648\u0644\u0627 \u062A\u0646\u0633\u0642 \u0645\u0639 \u0628\u0639\u0636\u0647\u0627 \u0627\u0644\u0628\u0639\u0636 \u0623\u0628\u062F\u064B\u0627.",
      "install.capabilities.service.title": "\u062E\u062F\u0645\u0629",
      "install.capabilities.worker.line1": "\u064A\u0642\u0648\u0645 \u0628\u062A\u0634\u063A\u064A\u0644 \u0627\u0644\u0645\u062C\u062F\u0648\u0644 \u0648\u0642\u0627\u0626\u0645\u0629 \u0627\u0646\u062A\u0638\u0627\u0631 \u0627\u0644\u0645\u0647\u0627\u0645 \u0648\u0645\u062D\u0631\u0643 \u0627\u0644\u062A\u0646\u0641\u064A\u0630 \u0641\u064A \u0627\u0644\u062E\u0644\u0641\u064A\u0629 \u0644\u0644\u0646\u0634\u0631.",
      "install.capabilities.worker.line2": "\u064A\u062A\u0639\u0627\u0645\u0644 \u0645\u0639 \u0627\u0644\u0639\u0645\u0644 \u063A\u064A\u0631 \u0627\u0644\u0645\u062A\u0632\u0627\u0645\u0646 \u0648\u0627\u0644\u0645\u062C\u062F\u0648\u0644 \u0628\u062D\u064A\u062B \u062A\u0638\u0644 \u0639\u0642\u062F \u0627\u0644\u062E\u062F\u0645\u0629 \u0633\u0631\u064A\u0639\u0629 \u0644\u0644\u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0627\u0644\u062A\u0641\u0627\u0639\u0644\u064A.",
      "install.capabilities.worker.line3": "\u0639\u0642\u062F\u0629 \u0639\u0627\u0645\u0644\u0629 \u0648\u0627\u062D\u062F\u0629 \u0628\u0627\u0644\u0636\u0628\u0637 \u0644\u0643\u0644 \u0639\u0645\u0644\u064A\u0629 \u0646\u0634\u0631 \u2014 \u0644\u0627 \u062A\u0628\u062F\u0623 \u0639\u0627\u0645\u0644\u064B\u0627 \u062B\u0627\u0646\u064A\u064B\u0627.",
      "install.capabilities.worker.title": "\u0639\u0627\u0645\u0644",
