      "install.database.sqlitePathHint": "\u064A\u0642\u0648\u0645 AppEndO \u0628\u0625\u0646\u0634\u0627\u0621 \u0645\u0644\u0641 SQLite \u0647\u0630\u0627 \u0648\u0623\u064A \u0645\u062C\u0644\u062F\u0627\u062A \u0623\u0635\u0644 \u0645\u0641\u0642\u0648\u062F\u0629 \u0623\u062B\u0646\u0627\u0621 \u0627\u0644\u062A\u062B\u0628\u064A\u062A - \u0644\u064A\u0633 \u0647\u0646\u0627\u0643 \u062D\u0627\u062C\u0629 \u0625\u0644\u0649 \u0645\u0644\u0641 \u0642\u0627\u0639\u062F\u0629 \u0628\u064A\u0627\u0646\u0627\u062A \u0645\u0648\u062C\u0648\u062F.",
      "install.database.sqlitePathPlaceholder": "\u0627\u0644\u0645\u0633\u0627\u0631: data/appendo-control.db",
      "install.database.sqliteWarning": "\u064A\u0646\u0627\u0633\u0628 SQLite \u0627\u0644\u062A\u0639\u0644\u0645 \u0648\u0627\u0644\u0639\u0631\u0648\u0636 \u0627\u0644\u062A\u0648\u0636\u064A\u062D\u064A\u0629 \u0648\u0627\u0644\u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0627\u0644\u062E\u0641\u064A\u0641 \u0645\u0639 \u0639\u062F\u062F \u0642\u0644\u064A\u0644 \u0645\u0646 \u0627\u0644\u0645\u0633\u062A\u062E\u062F\u0645\u064A\u0646 \u0648\u0642\u0644\u064A\u0644 \u0645\u0646 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A. \u0625\u0646\u0647 \u063A\u064A\u0631 \u0645\u0646\u0627\u0633\u0628 \u0644\u0623\u062D\u0645\u0627\u0644 \u0639\u0645\u0644 \u0627\u0644\u0625\u0646\u062A\u0627\u062C \u0623\u0648 \u062D\u0631\u0643\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0627\u0644\u0643\u062B\u064A\u0641\u0629.",
