  "hwy.membership.wizard.nakhebin.required": "\u0642\u0628\u0644 \u0627\u0632 \u062A\u0623\u06CC\u06CC\u062F\u060C \u0639\u0636\u0648 \u0631\u0627 \u0628\u0647 \u0633\u062C\u0644 \u0631\u0623\u06CC\u200C\u062F\u0647\u0646\u062F\u0647 \u067E\u06CC\u0648\u0646\u062F \u062F\u0647\u06CC\u062F.",
