function resolveSecurityClearanceStatusTone(statusTitle) {
  const normalized = statusTitle.trim().toLowerCase();
  if (!normalized || normalized === "\u2014" || normalized === "-") {
    return "neutral";
  }
  if (/مسموح|allowed|yes|نعم|موافق|permit/.test(normalized)) {
    return "success";
  }
  if (/قيد|study|pending|await|مراج|under review/.test(normalized)) {
    return "warning";
  }
  if (/ممنو|denied|reject|refus|no\b|لا|مرفوض|forbid/.test(normalized)) {
    return "danger";
  }
  return "neutral";
}
