// src/shared/api/contracts/data-api/pivot.ts
init_zod();
var PIVOT_AGGREGATIONS = [
  "sum",
  "count",
  "avg",
  "min",
  "max",
  "countDistinct"
];
var PIVOT_SOURCE_KINDS = [
  "flat-sql",
  "star-schema",
  "olap-bridge",
  "mongo-aggregation",
  "elasticsearch-aggregation"
];
var PIVOT_DATE_GRAINS = ["day", "hour", "month"];
var pivotAxisFieldSchema = external_exports.object({
  field: external_exports.string().min(1),
  grain: external_exports.enum(PIVOT_DATE_GRAINS).optional()
}).strict();
var pivotMeasureSchema = external_exports.object({
  field: external_exports.string().min(1),
  aggregation: external_exports.enum(PIVOT_AGGREGATIONS)
}).strict();
var pivotFilterDslSchema = external_exports.record(
  external_exports.string(),
  external_exports.record(external_exports.string(), external_exports.union([external_exports.string(), external_exports.number(), external_exports.boolean(), external_exports.array(external_exports.string())]))
);
var pivotSourceSchema = external_exports.object({
  kind: external_exports.enum(PIVOT_SOURCE_KINDS),
  dataSourceId: external_exports.string().min(1).optional(),
  catalog: external_exports.string().min(1).optional(),
  cube: external_exports.string().min(1).optional(),
  collection: external_exports.string().min(1).optional(),
  index: external_exports.string().min(1).optional()
}).strict();
var pivotSpecSchema = external_exports.object({
  rows: external_exports.array(pivotAxisFieldSchema).default([]),
  columns: external_exports.array(pivotAxisFieldSchema).default([]),
  measures: external_exports.array(pivotMeasureSchema).min(1),
  filters: pivotFilterDslSchema.optional(),
  totals: external_exports.object({
    rows: external_exports.boolean().optional(),
    columns: external_exports.boolean().optional()
  }).strict().optional(),
  source: pivotSourceSchema.optional(),
  noCache: external_exports.boolean().optional()
}).strict();
var pivotAxisMemberSchema = external_exports.object({
  key: external_exports.string(),
  labels: external_exports.array(external_exports.unknown())
}).strict();
var pivotResultSchema = external_exports.object({
  rowAxis: external_exports.object({
    fields: external_exports.array(external_exports.string()),
    members: external_exports.array(pivotAxisMemberSchema)
  }).strict(),
  colAxis: external_exports.object({
    fields: external_exports.array(external_exports.string()),
    members: external_exports.array(pivotAxisMemberSchema)
  }).strict(),
  measures: external_exports.array(external_exports.object({
    field: external_exports.string(),
    aggregation: external_exports.string()
  }).strict()),
  cells: external_exports.array(external_exports.object({
    rowKey: external_exports.string(),
    colKey: external_exports.string(),
    values: external_exports.array(external_exports.number().nullable())
  }).strict())
}).strict();

// src/shared/api/contracts/dashboard-canvas.ts
var DASHBOARD_CANVAS_CONFIG_PROP = "dashboardCanvasConfig";
var DASHBOARD_PERSONALIZABLE_PROP = "dashboardPersonalizable";
var dashboardWidgetKindSchema = external_exports.enum(["chart", "kpi", "table", "text", "combo"]);
var dashboardFilterControlTypeSchema = external_exports.enum([
  "select",
  "multiSelect",
  "dateRange",
  "text",
  "numericRange"
]);
var dashboardDomainEntrySchema = external_exports.object({
  id: external_exports.string().min(1),
  label: external_exports.string().optional(),
  dataSourceRef: external_exports.unknown(),
  exposedFields: external_exports.array(external_exports.string().min(1)).default([])
}).strict();
var dashboardFilterDeclarationSchema = external_exports.object({
  id: external_exports.string().min(1),
  label: external_exports.string().min(1),
  domainEntryId: external_exports.string().min(1),
  field: external_exports.string().min(1),
  controlType: dashboardFilterControlTypeSchema,
  appliesToWidgetIds: external_exports.array(external_exports.string().min(1)).optional(),
  defaultValue: external_exports.unknown().optional()
}).strict();
var dashboardJoinablePairSchema = external_exports.object({
  domainEntryIdA: external_exports.string().min(1),
  fieldA: external_exports.string().min(1),
  domainEntryIdB: external_exports.string().min(1),
  fieldB: external_exports.string().min(1),
  label: external_exports.string().optional()
}).strict();
var dashboardTabDeclarationSchema = external_exports.object({
  id: external_exports.string().min(1),
  label: external_exports.string().min(1)
}).strict();
var dashboardLinkDeclarationSchema = external_exports.object({
  label: external_exports.string().min(1),
  target: external_exports.union([
    external_exports.object({ pageId: external_exports.string().min(1) }).strict(),
    external_exports.object({ url: external_exports.string().min(1) }).strict()
  ]),
  forwardFilterState: external_exports.boolean().optional()
}).strict();
var dashboardCanvasPageConfigSchema = external_exports.object({
  personalizable: external_exports.boolean().default(false),
  domain: external_exports.array(dashboardDomainEntrySchema).default([]),
  filters: external_exports.array(dashboardFilterDeclarationSchema).optional(),
  joinablePairs: external_exports.array(dashboardJoinablePairSchema).optional(),
  tabs: external_exports.array(dashboardTabDeclarationSchema).optional(),
  dashboardLinks: external_exports.array(dashboardLinkDeclarationSchema).optional()
}).strict();
var dashboardGridPositionSchema = external_exports.object({
  x: external_exports.number().int().nonnegative(),
  y: external_exports.number().int().nonnegative(),
  w: external_exports.number().int().positive(),
  h: external_exports.number().int().positive()
}).strict();
var dashboardComboRefSchema = external_exports.object({
  domainEntryIdA: external_exports.string().min(1),
  fieldA: external_exports.string().min(1),
  domainEntryIdB: external_exports.string().min(1),
  fieldB: external_exports.string().min(1)
}).strict();
var dashboardUserWidgetSchema = external_exports.object({
  id: external_exports.string().min(1),
  tabId: external_exports.string().min(1).optional(),
  kind: dashboardWidgetKindSchema,
  domainEntryId: external_exports.string().min(1).optional(),
  comboRef: dashboardComboRefSchema.optional(),
  fieldMapping: external_exports.unknown().optional(),
  vizConfig: external_exports.unknown().optional(),
  gridPosition: dashboardGridPositionSchema
}).strict();
var dashboardSavedViewSchema = external_exports.object({
  id: external_exports.string().min(1),
  name: external_exports.string().min(1),
  urlQueryString: external_exports.string(),
  createdAt: external_exports.string().min(1)
}).strict();
var dashboardCanvasPersonalizationSchema = external_exports.object({
  hiddenNodeIds: external_exports.array(external_exports.string()).default([]),
  order: external_exports.array(external_exports.string()).default([]),
  sizes: external_exports.record(external_exports.string(), external_exports.object({
    w: external_exports.number().int().positive(),
    h: external_exports.number().int().positive()
  }).strict()).default({}),
  variantSelections: external_exports.record(external_exports.string(), external_exports.string()).default({}),
  userWidgets: external_exports.array(dashboardUserWidgetSchema).default([]),
  savedViews: external_exports.array(dashboardSavedViewSchema).default([])
}).strict();
var dashboardCanvasPivotRequestSchema = external_exports.object({
  pageId: external_exports.string().min(1),
  domainEntryId: external_exports.string().min(1),
  spec: pivotSpecSchema,
  widgetNodeId: external_exports.string().min(1).optional()
}).strict();
var dashboardAccessPermissionSchema = external_exports.enum(["view", "personalize"]);
var serializeDashboardCanvasPageConfig = (config2) => JSON.stringify(dashboardCanvasPageConfigSchema.parse(config2));

