// src/features/base-components/catalog/baseComponentOptionProvenance.ts
var isProductionOption = (option2) => (option2.disposition === "public-prop" || option2.disposition === "composition-prop") && typeof option2.propPath === "string" && option2.propPath.length > 0;
function attachBaseComponentOptionProvenance(options2, components2, demos2, tests2) {
  const componentsById = new Map(components2.map((component) => [component.id, component]));
  return options2.map((option2) => {
    const grouped = {
      ...option2,
      inspectorGroup: option2.inspectorGroup ?? resolveCatalogInspectorGroup(option2.id, void 0, option2.axis)
    };
    if (grouped.disposition !== "public-prop" && grouped.disposition !== "composition-prop") {
      return grouped;
    }
    if (!isProductionOption(option2)) {
      throw new Error(`Production option "${option2.id}" requires an explicit propPath.`);
    }
    const component = componentsById.get(option2.componentId);
    const primaryDemos = demos2.filter(
      (demo) => demo.componentId === option2.componentId && demo.primary
    );
    const livenessTests = tests2.filter(
      (test) => test.componentId === option2.componentId && test.testId.endsWith(".option-liveness")
    );
    if (!component) throw new Error(`Unknown production option owner "${option2.componentId}".`);
    if (primaryDemos.length !== 1) {
      throw new Error(`Production option "${option2.id}" requires exactly one primary demo.`);
    }
    if (livenessTests.length !== 1) {
      throw new Error(`Production option "${option2.id}" requires exactly one liveness test.`);
    }
    return {
      ...grouped,
      provenance: {
        ownerId: component.id,
        productionExportIds: component.publicExportIds,
        adapter: option2.disposition === "public-prop" ? "component-prop" : "composition-prop",
        propPath: option2.propPath,
        demoId: primaryDemos[0].id,
        livenessTestId: livenessTests[0].testId,
        livenessTestFile: livenessTests[0].testFile
      }
    };
  });
}

