// src/shared/ui/recordSubjectTimeline/recordSubjectTimelineSpineLayout.ts
function parseRecordSubjectTimelineYear(occurredAt) {
  const ms = Date.parse(occurredAt);
  if (!Number.isFinite(ms)) {
    return null;
  }
  return new Date(ms).getUTCFullYear();
}
function orderRecordSubjectTimelineEvents(events2, direction2) {
  const sorted = [...events2].sort(
    (left, right) => new Date(left.occurredAt).getTime() - new Date(right.occurredAt).getTime()
  );
  return direction2 === "newestFirst" ? sorted.reverse() : sorted;
}
function resolveRecordSubjectTimelineYearDividerYears(events2) {
  const years = [];
  let lastYear = null;
  events2.forEach((event) => {
    const year = parseRecordSubjectTimelineYear(event.occurredAt);
    if (year === null) {
      return;
    }
    if (lastYear === null || year !== lastYear) {
      years.push(year);
      lastYear = year;
    }
  });
  return years;
}
function assertRecordSubjectTimelineYearDividerOrder(years, direction2) {
  for (let index = 1; index < years.length; index += 1) {
    const previous = years[index - 1];
    const current = years[index];
    if (direction2 === "newestFirst" && current > previous) {
      throw new Error("Timeline year dividers must decrease top-to-bottom when newest is first.");
    }
    if (direction2 === "oldestFirst" && current < previous) {
      throw new Error("Timeline year dividers must increase top-to-bottom when oldest is first.");
    }
  }
}
function buildRecordSubjectTimelineSpineRows(events2, direction2, options2) {
  const ordered = options2?.preserveEventOrder ? [...events2] : orderRecordSubjectTimelineEvents([...events2], direction2);
  const dividerYears = resolveRecordSubjectTimelineYearDividerYears(ordered);
  assertRecordSubjectTimelineYearDividerOrder(dividerYears, direction2);
  const rows = [];
  let lastYear = null;
  let dividerSequence = 0;
  ordered.forEach((event, eventIndex) => {
    const year = parseRecordSubjectTimelineYear(event.occurredAt);
    if (year !== null && (lastYear === null || year !== lastYear)) {
      rows.push({
        kind: "year",
        year,
        key: `year-divider-${dividerSequence}-${year}`
      });
      dividerSequence += 1;
      lastYear = year;
    }
    rows.push({ kind: "event", event, eventIndex });
  });
  return rows;
}

